import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.map.js";
import api from '../services/api';
export default {
  name: 'CustomerRegister',
  data() {
    return {
      formData: {
        username: '',
        email: '',
        password: '',
        full_name: '',
        phone: '',
        address: ''
      },
      error: '',
      success: '',
      loading: false,
      agreedToTerms: false,
      showTerms: false
    };
  },
  methods: {
    async handleRegister() {
      this.error = '';
      this.success = '';
      if (!this.agreedToTerms) {
        this.error = 'Please agree to the Terms and Conditions and Data Privacy policy.';
        return;
      }
      this.loading = true;
      try {
        const response = await api.post('/customer/auth/register', this.formData);
        this.success = response.data.message;

        // Clear form
        this.formData = {
          username: '',
          email: '',
          password: '',
          full_name: '',
          phone: '',
          address: ''
        };
        this.agreedToTerms = false;

        // Redirect to login after 2 seconds
        setTimeout(() => {
          this.$router.push('/customer/login');
        }, 2000);
      } catch (err) {
        let message = err.response?.data?.message;
        if (!message && Array.isArray(err.response?.data?.errors)) {
          message = err.response.data.errors.map(error => error.msg).join('; ');
        }
        this.error = message || 'Registration failed. Please try again.';
      } finally {
        this.loading = false;
      }
    }
  }
};
